"""Independent reciprocal-trig identities, root/domain and graph checks."""
import argparse,json,math
from pathlib import Path
import sympy as s
p=argparse.ArgumentParser();p.add_argument('--output',type=Path,required=True);args=p.parse_args();checks=[];R=s.Rational;x=s.symbols('x',real=True);pi=s.pi

def ck(label,a,b):
 ok=s.simplify(s.trigsimp(a-b,method="fu"))==0;checks.append({'check':label,'passed':bool(ok)})
 if not ok:raise AssertionError((label,a,b))
def near(label,a,b,tol=1e-10):
 ok=abs(float(a)-b)<tol;checks.append({'check':label,'passed':ok})
 if not ok:raise AssertionError((label,a,b))
for label,a,b in [('6.1.1a',s.sec(pi/6),2*s.sqrt(3)/3),('6.1.1b',s.csc(5*pi/4),-s.sqrt(2)),('6.1.1c',s.cot(7*pi/6),s.sqrt(3)),('6.1.3a',s.sec(5*pi/6),-2*s.sqrt(3)/3),('6.1.3b',s.cot(-3*pi/4),1),('6.1.3c',s.csc(3*pi/2),-1),('6.1.4a',s.sec(pi/3)/s.csc(3*pi/2),-2),('6.1.4b',s.csc(3*pi/4)*s.cot(pi/6),s.sqrt(6)),('6.1.6 opposite',s.sqrt(25-16),3),('6.1.7',s.cot(pi/3)-s.csc(pi/4),(s.sqrt(3)-3*s.sqrt(2))/3)]:ck(label,a,b)
for label,a,b,tol in [('6.1.2a',s.cot(R(36,10)),2.03,.005),('6.1.2b',s.csc(153*pi/180),2.20,.005),('6.1.2c',s.sec(7*pi/4),1.41,.005),('6.5.6 y-intercept',2*s.atan(3),2.498,.0005)]:near(label,a,b,tol)
identities=[('6.1.5a',s.sec(-x),s.sec(x)),('6.1.5b',s.cot(x+pi),s.cot(x)),('6.2.2a',s.cot(x),-s.tan(x-pi/2)),('6.2.2b',s.csc(x),s.sec(x-pi/2)),('6.3.2a',s.cos(x)*s.cot(x)+s.sin(x),s.csc(x)),('6.3.2b',1/(s.cos(x)*s.tan(x)),s.csc(x)),('6.3.2c',s.cot(3*x)*s.sec(3*x),s.csc(3*x)),('6.3.4',(s.cot(x)+s.tan(x))/s.sec(x),s.csc(x)),('6.3.5',s.cos(3*x)+s.sin(3*x)*s.tan(3*x),s.sec(3*x)),('6.3.7',s.sin(x)/(1+s.cos(x))+(1+s.cos(x))/s.sin(x),2*s.csc(x)),('6.4.1a',s.csc(x)**2+s.tan(x)**2,s.sec(x)**2+s.cot(x)**2),('6.4.1b',s.cot(x)**2+s.cos(x)**2,(s.csc(x)-s.sin(x))*(s.csc(x)+s.sin(x))),('6.4.1c',1/(1+s.sin(x))+1/(1-s.sin(x)),2+2*s.tan(x)**2),('setA bronze',s.cos(x)/(1-s.sin(x))+(1-s.sin(x))/s.cos(x),2*s.sec(x)),('setA silver a',s.cot(x)**2+s.csc(x)**2,2*s.csc(x)**2-1),('setA gold',(1-s.tan(x)**2)/(1+s.tan(x)**2),1-2*s.sin(x)**2),('exam42',s.sec(x)**4-s.tan(x)**4,2*s.sec(x)**2-1)]
for label,a,b in identities:ck(label,a,b)
for label,f,points,values in [('6.2.1a',s.sec(x),[0,pi,2*pi,s.acos(R(1,3)),2*pi-s.acos(R(1,3))],[1,-1,1,3,3]),('6.2.3a',1+s.csc(x),[pi/2,3*pi/2],[2,0]),('6.2.3b',-s.cot(x/2),[pi],[0]),('6.2.3c',3*s.sec(2*x),[0,pi/2,pi,3*pi/2,2*pi],[3,-3,3,-3,3]),('6.2.4',s.csc(x+pi/4),[0,pi/4,9*pi/4,5*pi/4,13*pi/4],[s.sqrt(2),1,1,-1,-1]),('6.2.5',2+4*s.sec(x),[-2*pi,-pi,0,pi,2*pi],[6,-2,6,-2,6]),('6.2.6',s.cot(3*x),[pi/6,pi/2,5*pi/6],[0,0,0]),('6.2.7',2+3*s.csc(x),[-pi/2,pi/2],[-1,5]),('6.5.4',pi/3+s.asin(x-R(1,2)),[-R(1,2),R(3,2),(1-s.sqrt(3))/2],[-pi/6,5*pi/6,0]),('setB bronze',s.tan(2*x),[0,pi/2,pi],[0,0,0]),('exam58',s.acos(x/2),[-2,0,2],[pi,pi/2,0])]:
 for z,w in zip(points,values):ck(label+' value '+str(z),f.subs(x,z),w)
# Verify original equations at every unrounded root and test the required intervals.
a=s.asin(R(1,4));b=s.asin(R(2,5));c=s.asin(6/(9+s.sqrt(105)));d=s.asin(s.sqrt(5)-2)
rootsets=[('6.3.3a',s.csc(x)-2,[pi/6,5*pi/6],0,2*pi),('6.3.3b',s.sqrt(3)*s.sec(x)-4,[s.acos(s.sqrt(3)/4),2*pi-s.acos(s.sqrt(3)/4)],0,2*pi),('6.3.3c',3*s.cot(x)+R(5,2),[pi-s.atan(R(6,5)),2*pi-s.atan(R(6,5))],0,2*pi),('6.3.4',(s.cot(x)+s.tan(x))/s.sec(x)-4,[a,pi-a],0,2*pi),('6.3.6',3*s.sin(x)-8*s.cot(x),[s.acos(R(1,3)),2*pi-s.acos(R(1,3))],0,2*pi),('6.3.7',s.sin(x-pi/6)/(1+s.cos(x-pi/6))+(1+s.cos(x-pi/6))/s.sin(x-pi/6)-5,[pi/6+b,7*pi/6-b],0,2*pi),('6.4.3a',s.sec(x)**2+s.tan(x)-1,[-pi,-pi/4,0,3*pi/4,pi],-pi,pi),('6.4.3b',3*s.cot(x)**2+9*s.csc(x)+1,[pi+c,2*pi-c],0,2*pi),('6.4.3c',s.csc(x)**2+s.cot(x)**2-3,[pi/4,3*pi/4,5*pi/4,7*pi/4],0,2*pi),('6.4.5',s.sec(x)**2-5-3*s.tan(x),[s.atan(4),3*pi/4,pi+s.atan(4),7*pi/4],0,2*pi),('6.4.6',s.cot(x)**2+4*s.csc(x),[pi+d,2*pi-d],0,2*pi),('6.4.7',2*s.csc(x)**2+5*s.cot(x)-5,[s.atan(2)-pi,-s.atan(R(1,3)),s.atan(2),pi-s.atan(R(1,3))],-pi,pi),('setB bronze',s.cot(2*x)**2-4*s.cot(2*x)+4,[s.atan(R(1,2))/2,s.atan(R(1,2))/2+pi/2],0,pi),('setB silver',4*s.cot(2*x)**2+12*s.csc(2*x)+9,[(pi+b)/2,(2*pi-b)/2,(3*pi+b)/2,(4*pi-b)/2],0,2*pi),('setB gold',5+2*s.cot(2*x+pi/3)**2-7*(1+s.csc(2*x+pi/3)),[(pi-a-pi/3)/2,(2*pi+a-pi/3)/2,(3*pi-a-pi/3)/2,(4*pi+a-pi/3)/2],0,2*pi),('exam6',4*s.cos(x)-3*s.sec(x),[-5*pi/6,-pi/6,pi/6,5*pi/6],-pi,pi),('exam42',s.sec(x)**4-s.tan(x)**4-24,[s.acos(s.sqrt(2)/5),pi-s.acos(s.sqrt(2)/5),pi+s.acos(s.sqrt(2)/5),2*pi-s.acos(s.sqrt(2)/5)],0,2*pi)]
for label,f,values,lo,hi in rootsets:
 for i,v in enumerate(values):
  near(label+' root '+str(i),f.subs(x,v).evalf(30),0,1e-25);ck(label+' interval '+str(i),int(float(lo)<=float(v)<=float(hi)),1)
# Check printed rounding independently of the symbolic derivation.
roundings=[('6.3.3b',[s.acos(s.sqrt(3)/4)*180/pi,(2*pi-s.acos(s.sqrt(3)/4))*180/pi],[64.3,296],[.05,.5]),('6.3.3c',[(pi-s.atan(R(6,5)))*180/pi,(2*pi-s.atan(R(6,5)))*180/pi],[130,310],[.5,.5]),('6.3.4',[a*180/pi,(pi-a)*180/pi],[14.5,166],[.05,.5]),('6.3.6',[s.acos(R(1,3)),2*pi-s.acos(R(1,3))],[1.23,5.05],[.005,.005]),('6.3.7',[pi/6+b,7*pi/6-b],[.935,3.25],[.0005,.005]),('6.4.3b',[pi+c,2*pi-c],[3.46,5.97],[.005,.005]),('6.4.5',[s.atan(4)*180/pi,180+s.atan(4)*180/pi],[76,256],[.05,.05]),('6.4.6',[pi+d,2*pi-d],[3.4,6],[.05,.05]),('6.4.7',[s.atan(2)-pi,-s.atan(R(1,3)),s.atan(2),pi-s.atan(R(1,3))],[-2.03,-.32,1.11,2.82],[.005]*4),('setB bronze',[s.atan(R(1,2))/2,s.atan(R(1,2))/2+pi/2],[.23,1.80],[.005]*2),('setB silver',[(pi+b)*90/pi,(2*pi-b)*90/pi,(3*pi+b)*90/pi,(4*pi-b)*90/pi],[101.8,168.2,281.8,348.2],[.05]*4),('setB gold',[(pi-a-pi/3)/2,(2*pi+a-pi/3)/2,(3*pi-a-pi/3)/2,(4*pi+a-pi/3)/2],[.92,2.74,4.06,5.89],[.005]*4),('exam42',[s.acos(s.sqrt(2)/5)*180/pi,180-s.acos(s.sqrt(2)/5)*180/pi,180+s.acos(s.sqrt(2)/5)*180/pi,360-s.acos(s.sqrt(2)/5)*180/pi],[73.57,106.4,253.6,286.4],[.005,.05,.05,.05])]
for label,values,expected,tolerances in roundings:
 for i,(v,w,t) in enumerate(zip(values,expected,tolerances)):near(label+' rounding '+str(i),v,w,t)
for label,a,b in [('6.4.2 cosine',-s.sqrt(1-R(16,25)),-R(3,5)),('6.4.4 cosine',-s.sqrt(1-R(2,9)),-s.sqrt(7)/3),('6.4.6 rationalization',1/(-2-s.sqrt(5)),2-s.sqrt(5)),('6.5.2a',s.atan(1),pi/4),('6.5.2b',s.asin(-s.sqrt(3)/2),-pi/3),('6.5.2c',s.acos(R(1,2)),pi/3),('6.5.3a',s.asin(s.sin(pi/2)),pi/2),('6.5.3b',s.acos(s.cos(3*pi)),pi),('6.5.3c',s.atan(s.tan(5*pi/4)),pi/4),('6.5.5',s.acos(s.sqrt(3)/2)+s.acos(-R(1,2)),5*pi/6),('6.5.7 supplied root residual',s.acos(s.sqrt(2)/2)+pi/4,pi/2),('exam21 cot',(-1/s.sqrt(5))*(-2),2/s.sqrt(5))]:ck(label,a,b)
# Independent polynomial count for the two graph intersections in exam 15.
t=s.symbols('t');poly=s.Poly((1-t*t)**2-12*t,t)
ck('exam15 first-quadrant root count',poly.count_roots(0,1),1);ck('exam15 second-quadrant root count',poly.count_roots(1,s.oo),1)
ck('exam15 positive reciprocal max',1/(3+3*s.sec(0)),R(1,6));ck('6.2.7 reciprocal max',1/(2+3*s.csc(pi/2)),R(1,5))
args.output.write_text(json.dumps(checks,indent=2)+'\n');print(len(checks),'independent checks passed')
